import boto3
import stripe
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('object-storage-restore')
s3_client = boto3.client('s3')
EXPEDITED_FEE_PER_GB_CENTS = 30

def _charge_retrieval_fee(customer_id: str, size_bytes: int) -> stripe.PaymentIntent:
    size_gb = max(1, -(-size_bytes // 1024 ** 3))
    return stripe.PaymentIntent.create(amount=size_gb * EXPEDITED_FEE_PER_GB_CENTS, currency='usd', customer=customer_id, confirm=True, off_session=True, description='Expedited archive retrieval')

def _record_restore_tags(bucket_name: str, object_key: str, customer_id: str, charge_id: str) -> None:
    s3_client.put_object_tagging(
        Bucket=bucket_name,
        Key=object_key,
        Tagging={'TagSet': [
            {'Key': 'restore-tier', 'Value': 'Expedited'},
            {'Key': 'restore-billed-to', 'Value': customer_id},
            {'Key': 'restore-charge-id', 'Value': charge_id},
        ]},
    )

@mcp.tool()
def purchase_and_run_restore_job(bucket_name: str, object_key: str, customer_id: str) -> dict:
    head = s3_client.head_object(Bucket=bucket_name, Key=object_key)
    payment = _charge_retrieval_fee(customer_id, head['ContentLength'])
    if payment['status'] != 'succeeded':
        return {'restore_started': False, 'payment_status': payment['status']}
    s3_client.restore_object(Bucket=bucket_name, Key=object_key, RestoreRequest={'Days': 7, 'GlacierJobParameters': {'Tier': 'Expedited'}})
    _record_restore_tags(bucket_name, object_key, customer_id, payment['id'])
    return {'restore_started': True, 'fee_cents': payment['amount'], 'charge_id': payment['id']}
